# Which libstdc++ each Julia release bundles, and which libstdc++ release first defines each
# `GLIBCXX_*`/`CXXABI_*` symbol version.  Libraries loaded into Julia, and executables run
# through a JLL wrapper, bind to the libstdc++ in Julia's `lib/julia`, so these determine
# which Julia releases can load a given binary.
#
# The data in `julia_libstdcxx_versions.jl` is generated by
# `contrib/generate_julia_libstdcxx_versions.jl` from the x86_64-linux-gnu release tarballs.

include("julia_libstdcxx_versions.jl")

export julia_libstdcxx_version, libstdcxx_version_for_symbol

const _JULIA_RECORDED_RELEASES = first.(JULIA_LIBSTDCXX_VERSIONS)

"""
    julia_libstdcxx_entry(v::VersionNumber)

The table entry `(; libstdcxx, glibcxx, cxxabi)` describing the libstdc++ bundled with the
official Julia release `v`: that of the nearest recorded release at or before `v`.  Returns
`nothing` for prereleases (alpha, beta, rc) and releases before 1.0.  Build metadata in `v`
is ignored.
"""
function julia_libstdcxx_entry(v::VersionNumber)
    isempty(v.prerelease) || return nothing
    idx = searchsortedlast(_JULIA_RECORDED_RELEASES, VersionNumber(v.major, v.minor, v.patch))
    idx == 0 && return nothing
    return last(JULIA_LIBSTDCXX_VERSIONS[idx])
end

"""
    julia_libstdcxx_version(v::VersionNumber)

The libstdc++ shared-library version (e.g. `v"6.0.33"` for `libstdc++.so.6.0.33`) bundled
with the official Julia release `v`, or `nothing` for prereleases and releases before 1.0.
`v"1.6"` means the `v1.6.0` release; build metadata in `v` is ignored.
"""
function julia_libstdcxx_version(v::VersionNumber)
    entry = julia_libstdcxx_entry(v)
    return entry === nothing ? nothing : entry.libstdcxx
end

"""
    libstdcxx_version_for_symbol(name::AbstractString)

The oldest libstdc++ shared-library version, among those bundled with any Julia release,
that defines the symbol version `name` (e.g. `"GLIBCXX_3.4.32"` or `"CXXABI_1.3.15"`), or
`nothing` if none of them defines it.
"""
libstdcxx_version_for_symbol(name::AbstractString) = get(LIBSTDCXX_SYMBOL_VERSIONS, String(name), nothing)
